def test_nested_overflowing_child():
    config = Config()
    root = Node(config)
    root.position_type = PositionType.ABSOLUTE
    root.width = 100
    root.height = 100
    root_child0 = Node(config)
    root.insert_child(root_child0, 0)
    root_child0_child0 = Node(config)
    root_child0_child0.width = 200
    root_child0_child0.height = 200
    root_child0.insert_child(root_child0_child0, 0)
    root.calculate_layout(None, None, Direction.LTR)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(100, abs=1e-4)
    assert root.layout.height == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.left == pytest.approx(0, abs=1e-4)
    assert root_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0.layout.width == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.height == pytest.approx(200, abs=1e-4)
    assert root_child0_child0.layout.left == pytest.approx(0, abs=1e-4)
    assert root_child0_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0_child0.layout.width == pytest.approx(200, abs=1e-4)
    assert root_child0_child0.layout.height == pytest.approx(200, abs=1e-4)
    root.calculate_layout(None, None, Direction.RTL)
    assert root.layout.left == pytest.approx(0, abs=1e-4)
    assert root.layout.top == pytest.approx(0, abs=1e-4)
    assert root.layout.width == pytest.approx(100, abs=1e-4)
    assert root.layout.height == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.left == pytest.approx(0, abs=1e-4)
    assert root_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0.layout.width == pytest.approx(100, abs=1e-4)
    assert root_child0.layout.height == pytest.approx(200, abs=1e-4)
    assert root_child0_child0.layout.left == pytest.approx(-100, abs=1e-4)
    assert root_child0_child0.layout.top == pytest.approx(0, abs=1e-4)
    assert root_child0_child0.layout.width == pytest.approx(200, abs=1e-4)
    assert root_child0_child0.layout.height == pytest.approx(200, abs=1e-4)


